result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "ledger.py", "content": """"A minimal double-entry ledger library.

All amounts are integer cents. Every entry must balance: the sum of its
debit lines must equal the sum of its credit lines, exactly, to the cent.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Tuple


class LedgerError(Exception):
    """Base class for ledger errors."""


class UnbalancedEntryError(LedgerError):
    """Raised when an entry's debits do not equal its credits."""


def _validate_amount(amount: int) -> int:
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise TypeError(f"amount must be an integer number of cents, got {amount!r}")
    if amount <= 0:
        raise ValueError(f"line amount must be a positive integer of cents, got {amount}")
    return amount


@dataclass(frozen=True)
class Line:
    """A single debit or credit line against an account."""

    account: str
    amount: int  # integer cents, always positive
    side: str  # "debit" or "credit"

    def __post_init__(self) -> None:
        _validate_amount(self.amount)
        if self.side not in ("debit", "credit"):
            raise ValueError(f"side must be 'debit' or 'credit', got {self.side!r}")


@dataclass(frozen=True)
class Entry:
    """An immutable set of debit/credit lines that must net to zero."""

    lines: Tuple[Line, ...] = field(default_factory=tuple)
    memo: str = ""

    @staticmethod
    def build(
        debits: Iterable[Tuple[str, int]],
        credits: Iterable[Tuple[str, int]],
        memo: str = "",
    ) -> "Entry":
        """Construct an Entry from (account, cents) pairs.

        Raises UnbalancedEntryError if debits != credits to the cent.
        """
        lines = [Line(acct, amt, "debit") for acct, amt in debits]
        lines += [Line(acct, amt, "credit") for acct, amt in credits]
        entry = Entry(tuple(lines), memo)
        total_debits = sum(l.amount for l in lines if l.side == "debit")
        total_credits = sum(l.amount for l in lines if l.side == "credit")
        if total_debits != total_credits:
            raise UnbalancedEntryError(
                f"debits ({total_debits}) != credits ({total_credits})"
                + (f" for entry {memo!r}" if memo else "")
            )
        return entry

    @property
    def debits(self) -> int:
        return sum(l.amount for l in self.lines if l.side == "debit")

    @property
    def credits(self) -> int:
        return sum(l.amount for l in self.lines if l.side == "credit")


class Ledger:
    """An append-only double-entry ledger."""

    def __init__(self) -> None:
        self.entries: List[Entry] = []
        # account -> {"debit": cents, "credit": cents}
        self._tally: Dict[str, Dict[str, int]] = {}

    def post(self, entry: Entry) -> Entry:
        """Append a balanced entry to the ledger.

        Raises UnbalancedEntryError and leaves the ledger unchanged if the
        entry's debit total does not equal its credit total.
        """
        if entry.debits != entry.credits:
            raise UnbalancedEntryError(
                f"rejected: debits ({entry.debits}) != credits ({entry.credits})"
            )
        self.entries.append(entry)
        for line in entry.lines:
            tally = self._tally.setdefault(line.account, {"debit": 0, "credit": 0})
            tally[line.side] += line.amount
        return entry

    def trial_balance(self) -> Dict[str, int]:
        """Net per-account balances such that all values sum to zero.

        Debit-normal accounts (assets, expenses) are positive;
        credit-normal accounts (liabilities, equity, revenue) are negative.
        """
        return {
            acct: tally["debit"] - tally["credit"]
            for acct, tally in sorted(self._tally.items())
        }

    @property
    def total_debits(self) -> int:
        return sum(e.debits for e in self.entries)

    @property
    def total_credits(self) -> int:
        return sum(e.credits for e in self.entries)
